import { Component, Emit, Prop, Vue } from 'vue-property-decorator';
import { OverlaysEventEmitter } from '../../event-emitter';
import { ISelfExclusionTranslations } from '../../translations';

@Component({
    name: 'SelfExclusion'
})
export default class SelfExclusion extends Vue {
    @Prop({
        required: false,
        type: Object,
        default() {
            return {
                header: 'Game Access Limited',
                message: 'You are currently excluded from this game',
                closeGameLabel: 'Close Game',
                logoutLabel: 'Logout'
            };
        }
    })
    public translations: ISelfExclusionTranslations;

    public isVisible: boolean = false;

    public created() {
        this.show = this.show.bind(this);
        this.hide = this.hide.bind(this);
    }

    public mounted() {
        OverlaysEventEmitter.on('showSelfExclusion', this.show, this);
        OverlaysEventEmitter.on('hideSelfExclusion', this.hide, this);
    }

    public beforeDestroy() {
        OverlaysEventEmitter.off('showSelfExclusion', this.show, this);
        OverlaysEventEmitter.off('hideSelfExclusion', this.hide, this);
    }

    public show() {
        this.isVisible = true;
    }

    public hide() {
        this.isVisible = false;
    }

    @Emit('onClose')
    public onCloseGame() {
        this.hide();
    }

    @Emit('onLogout')
    public onLogout() {
        this.hide();
    }
}
